# Generated by xc --completion bash. Reload after moving the Python environment.
[[ -n ${BASH_VERSION:-} ]] || return 0
_xcmd_conflict=0
_xcmd_legacy_conflict=0
for _xcmd_name in xc xcmd; do
_xcmd_conflict=0
_xcmd_existing=$(type -t "$_xcmd_name" 2>/dev/null) || _xcmd_existing=''
case $_xcmd_existing in
    '') ;;
    function)
        [[ $(declare -f "$_xcmd_name") == *'__xcmd_cli "$@"'* ||
           $(declare -f "$_xcmd_name") == *'python3 "$_XCMD_TOOL_BIN" "$@"'* ]] || _xcmd_conflict=1
        ;;
    file)
        _xcmd_path=$(type -P "$_xcmd_name")
        [[ $_xcmd_path -ef @XC_SOURCE_ENTRY@ || $_xcmd_path -ef @XC_CONSOLE_ENTRY@ ||
           $_xcmd_path -ef @SOURCE_ENTRY@ || $_xcmd_path -ef @CONSOLE_ENTRY@ ||
           $_xcmd_path -ef $HOME/bin/cmd-tool/xc ||
           $_xcmd_path -ef $HOME/bin/cmd-tool/xcmd ||
           $_xcmd_path -ef ${XDG_DATA_HOME:-$HOME/.local/share}/cmd-tool/xcmd ]] || _xcmd_conflict=1
        ;;
    *) _xcmd_conflict=1 ;;
esac
if (( _xcmd_conflict )); then
    if [[ $_xcmd_name == xcmd ]]; then
        _xcmd_legacy_conflict=1
        printf 'xc: legacy xcmd alias skipped; an unrelated xcmd command exists.\n' >&2
        continue
    fi
    printf 'xc: an unrelated %s command already exists; completion was not loaded.\n' "$_xcmd_name" >&2
    unset _xcmd_existing _xcmd_conflict _xcmd_path _xcmd_name _xcmd_legacy_conflict
    return 1
fi
done
unset _xcmd_existing _xcmd_conflict _xcmd_path _xcmd_name
__xcmd_python=@PYTHON@
__xcmd_runner=@RUNNER@
__xcmd_cli() { "$__xcmd_python" "$__xcmd_runner" "$@"; }
xc() { __xcmd_cli "$@"; }
if (( ! _xcmd_legacy_conflict )); then
    xcmd() { __xcmd_cli "$@"; }
fi

_xcmd_tool_complete() {
    local cur=${COMP_WORDS[COMP_CWORD]} index=$COMP_CWORD first=1
    local matches name command prompt tail i
    COMPREPLY=()
    if [[ ${COMP_WORDS[1]:-} == --shell ]]; then
        if (( COMP_CWORD == 2 )); then
            mapfile -t COMPREPLY < <(compgen -W 'bash powershell' -- "$cur")
            return 0
        fi
        first=3
        ((index -= 2))
    fi
    if (( index > 1 )); then
        if ! (( index == 2 )) || [[ ${COMP_WORDS[first]} != --show ]]; then
            compopt -o default 2>/dev/null
            return 0
        fi
    fi
    if [[ $cur == -* ]]; then
        mapfile -t COMPREPLY < <(compgen -W '--list --show --config --init --edit --completion --install-completion --shell --version --help' -- "$cur")
        return 0
    fi
    matches=$(__xcmd_cli --complete "$cur") || return 0
    [[ -n $matches ]] || return 0
    printf '\n'
    while IFS=$'\t' read -r name command; do
        [[ -n $name ]] || continue
        COMPREPLY+=("$name")
        printf '  %s -- %s\n' "$name" "$command"
    done <<< "$matches"
    prompt=${PS1@P}
    prompt=${prompt//$'\001'/}
    prompt=${prompt//$'\002'/}
    printf '%s%s' "$prompt" "$COMP_LINE"
    tail=${COMP_LINE:COMP_POINT}
    for ((i = 0; i < ${#tail}; i++)); do printf '\b'; done
}
complete -F _xcmd_tool_complete xc
if (( ! _xcmd_legacy_conflict )); then
    complete -F _xcmd_tool_complete xcmd
fi
unset _xcmd_legacy_conflict

if [[ $(declare -f cmd 2>/dev/null) == *'python3 "$_CMD_TOOL_BIN" "$@"'* ]]; then
    unset -f cmd
    unset _CMD_TOOL_BIN
fi
if [[ $(complete -p cmd 2>/dev/null) == *'-F _cmd_tool_complete cmd' ]]; then
    complete -r cmd
    unset -f _cmd_tool_complete
fi
